"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["38331"],{78912(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.janela_invertida","status":422,"titulo":"A data de t\xe9rmino do per\xedodo da etapa \xe9 anterior \xe0 data de in\xedcio"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.janela_invertida","requisitos":[],"oQueAconteceu":["Uma das etapas do pedido de defini\xe7\xe3o de etapas\\n(`PUT .../processos-seletivos/{id}/etapas`) foi declarada com per\xedodo pr\xf3prio\\n(`inicio` e `fim`), e o `fim` \xe9 anterior ao `inicio`. O per\xedodo com fim igual ao\\nin\xedcio \xe9 aceito; s\xf3 o fim anterior ao in\xedcio \xe9 recusado.","A recusa **n\xe3o \xe9 acumulada** com as demais: ela vem depois da confer\xeancia da\\nforma, do car\xe1ter e da avalia\xe7\xe3o de todas as etapas, e \xe9 conferida etapa por\\netapa, na ordem do pedido, depois da declara\xe7\xe3o dos atos de cada etapa\\n([`ato_duplicado_na_etapa`](/erros/uniplus.selecao.etapa_processo.ato_duplicado_na_etapa))\\ne antes da declara\xe7\xe3o das bancas. A primeira etapa com problema interrompe a\\nconfer\xeancia e a resposta traz s\xf3 essa recusa, sem indicar qual \xe9 a etapa; as\\netapas seguintes s\xf3 s\xe3o conferidas depois que ela for corrigida. Nada \xe9\\ngravado.","A confer\xeancia de que o per\xedodo da etapa cabe dentro do per\xedodo da fase \xe9 outra, com\\nrecusa pr\xf3pria."],"comoResolver":["Corrija `inicio` e `fim` da etapa que est\xe1 com o per\xedodo invertido (confira o dia\\ne o fuso) e reenvie a defini\xe7\xe3o. Se o pedido tem mais de uma etapa com per\xedodo,\\nconfira todas: as demais aparecem s\xf3 depois."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);